/*
Use OPC to get new output

Rhythm of light 光之韻
Made for #WCCChallenge topic "Simplify 😶" by TKt

While searching for reference images of "Simplify",
I came across several images that turned messy lines 
into straight ones, which inspired this creation.

I practiced the 3D features of p5.js in this sketch. 
I haven't used this part much before, so I'm not very 
familiar with it. Setting up camera movement and rotation 
took me quite some time reading the p5js documentation 
and try.
*/

OPC.toggle("lineMode",false)
OPC.slider("nodeCount",50,5,100,1)

var nodes = []
var aniDuration = 1000

function setup() {
	const canvaSize = max(windowWidth, windowHeight)
	createCanvas(canvaSize,canvaSize, WEBGL);
	background(0)
	curveDetail(25)

	// set the start and end of the final line
	const startVec = createVector(-height,0,0)
	const endVec = createVector(height,0,0)
	const r = height

	nodes.push(new Node(startVec,0))
	for(let i=0;i<nodeCount;i++){
		const coor = p5.Vector.random3D().mult(randomGaussian(r,r*0.05))
		const dur = map(i,0,nodeCount,1,aniDuration)
		const node = new Node(coor,dur)
		const target = p5.Vector.lerp(startVec,endVec,(i/nodeCount))
		node.setTarget(target)
		nodes.push(node)
	}
	nodes.push(new Node(endVec,0))
	strokeWeight(3)
	colorMode(HSB)

}

function draw() {
	if(lineMode){
		background(0);
		noFill()
		stroke(100)
	}else{
		stroke(frameCount%360,70,100,0.01)
		noFill()
		blendMode(ADD)
	}

	// camera setting
	const cameraStart = createVector(-height,0,0)
	const cameraEnd = createVector(0,0,0)
	const cameraFace = p5.Vector.lerp(cameraStart,cameraEnd,easeOutSine(map(frameCount/aniDuration,0,1,0,1,true)))
	const cameraP = [cameraFace.x+height*1.7, cameraFace.y+sin(frameCount*0.01)*500, cameraFace.z+cos(frameCount*0.01)*500]
	camera(...cameraP, // the position of the camera
				cameraFace.x,cameraFace.y,cameraFace.z, // the point that the camera face at
				1,0,0) // the 'up' vertex of the camera
	perspective(1.4)

	// draw the nodes
	beginShape()
	curveVertex(nodes[0].p.x, nodes[0].p.y, nodes[0].p.z)
	curveVertex(nodes[0].p.x, nodes[0].p.y, nodes[0].p.z)
	for(let node of nodes){
		node.update()
		// node.show()
		curveVertex(node.p.x, node.p.y, node.p.z)
	}
	curveVertex(nodes[nodes.length-1].p.x, nodes[nodes.length-1].p.y, nodes[nodes.length-1].p.z)
	curveVertex(nodes[nodes.length-1].p.x, nodes[nodes.length-1].p.y, nodes[nodes.length-1].p.z)
	endShape()
}

function parameterChanged() {
	nodes = []
	frameCount = 0
	setup()
}

class Node{
	constructor(vec, duration){
		this.p = vec.copy()
		this.start = vec.copy()
		this.target = vec.copy()
		this.duration = duration
		this.t = 0
	}
	setTarget(vec){
		this.target = vec.copy()
	}
	update(){
		this.t = this.t<this.duration?this.t+1:this.duration
		let ratio = easeInOutCubic(this.t / this.duration)
		this.p = p5.Vector.lerp(this.start, this.target, ratio)
	}
	show(){
		circle(this.p.x,this.p.y,5)
	}
}

// easing function

function easeOutQuint(x) {
	return 1 - Math.pow(1 - x, 5);
}

function easeOutSine(x) {
  return Math.sin((x * Math.PI) / 2);
}

function easeInOutCubic(x) {
	return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
}

